export function localImageFor(sessionName: string, activityKey: string): string | undefined {
  const set = LOCAL_SESSION_IMAGES[sessionName];
  if (!set) return undefined;
  if (!set.keys.includes(activityKey)) return undefined;
  return `/session-images/${set.slug}/${activityKey}.jpg`;
}
